function largestFromTwoRows(nums1: number[], nums2: number[], k: number): number[] {
  const m = nums1.length, n = nums2.length;
  const memo = new Map<string, number[]>();
  const bigger = (x: number[], y: number[]) => {
    for (let t = 0; t < x.length; t++) if (x[t] !== y[t]) return x[t] > y[t];
    return false;
  };
  const best = (i: number, j: number, r: number): number[] => {
    if (r === 0) return [];
    const key = i + "," + j + "," + r;
    if (memo.has(key)) return memo.get(key)!;
    let res: number[] | null = null;
    for (let p = i; p < m; p++) {
      if (m - p - 1 + n - j < r - 1) break;
      const cand = [nums1[p], ...best(p + 1, j, r - 1)];
      if (!res || bigger(cand, res)) res = cand;
    }
    for (let q = j; q < n; q++) {
      if (m - i + n - q - 1 < r - 1) break;
      const cand = [nums2[q], ...best(i, q + 1, r - 1)];
      if (!res || bigger(cand, res)) res = cand;
    }
    memo.set(key, res!);
    return res!;
  };
  return best(0, 0, k);
}

