class Solution:
    def largestFromTwoRows(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        m, n = len(nums1), len(nums2)

        @lru_cache(maxsize=None)
        def best(i, j, r):
            if r == 0:
                return ()
            res = None
            for p in range(i, m):
                if m - p - 1 + n - j < r - 1:
                    break
                cand = (nums1[p],) + best(p + 1, j, r - 1)
                if res is None or cand > res:
                    res = cand
            for q in range(j, n):
                if m - i + n - q - 1 < r - 1:
                    break
                cand = (nums2[q],) + best(i, q + 1, r - 1)
                if res is None or cand > res:
                    res = cand
            return res

        return list(best(0, 0, k))

