function largestFromTwoRows(nums1: number[], nums2: number[], k: number): number[] {
  // largest subsequence of length t, keeping order
  const pick = (row: number[], t: number): number[] => {
    const st: number[] = [];
    let drop = row.length - t;
    for (const d of row) {
      while (drop > 0 && st.length && st[st.length - 1] < d) { st.pop(); drop--; }
      st.push(d);
    }
    return st.slice(0, t);
  };
  // is a[i..] lexicographically greater than b[j..]? (a longer tail wins a tie)
  const greater = (a: number[], i: number, b: number[], j: number): boolean => {
    while (i < a.length && j < b.length && a[i] === b[j]) { i++; j++; }
    return j === b.length || (i < a.length && a[i] > b[j]);
  };
  const merge = (a: number[], b: number[]): number[] => {
    const out: number[] = [];
    let i = 0, j = 0;
    while (i < a.length || j < b.length) out.push(greater(a, i, b, j) ? a[i++] : b[j++]);
    return out;
  };
  let best: number[] = [];
  for (let i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {
    const cand = merge(pick(nums1, i), pick(nums2, k - i));
    if (greater(cand, 0, best, 0)) best = cand;
  }
  return best;
}

