class Solution:
    def largestFromTwoRows(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        def pick(row, t):
            st, drop = [], len(row) - t
            for d in row:
                while drop and st and st[-1] < d:
                    st.pop()
                    drop -= 1
                st.append(d)
            return st[:t]

        def greater(a, i, b, j):
            # is a[i:] lexicographically greater than b[j:]? (a longer tail wins a tie)
            while i < len(a) and j < len(b) and a[i] == b[j]:
                i += 1
                j += 1
            return j == len(b) or (i < len(a) and a[i] > b[j])

        def merge(a, b):
            out, i, j = [], 0, 0
            while i < len(a) or j < len(b):
                if greater(a, i, b, j):
                    out.append(a[i])
                    i += 1
                else:
                    out.append(b[j])
                    j += 1
            return out

        best = []
        for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
            cand = merge(pick(nums1, i), pick(nums2, k - i))
            if cand > best:
                best = cand
        return best

